"""Public Prisma introduction. Describes the method; does not run an AI session."""
from html import escape as e
from home_sections import contact_link


def render_prisma(*, profiles, css, font, favicon, brand, footer, style_href, prisma_href, phone):
    cards=[]
    for n,p in enumerate(profiles,1):
        methods=''.join('<li>'+e(m)+'</li>' for m in p['methods'])
        cards.append(f'''<article class="expert" id="{e(p['slug'])}" aria-labelledby="expert-{n}">
<div class="expert-top"><span class="expert-number">0{n}</span><span>{e(p['lens'])}</span></div>
<h3 id="expert-{n}">{e(p['name'])}</h3><p class="expert-question">{e(p['question'])}</p><p>{e(p['summary'])}</p>
<details><summary>Conheça o olhar deste especialista <span aria-hidden="true">+</span></summary><div class="expert-detail"><h4>Como analisa</h4><ul>{methods}</ul><h4>O que coloca na mesa</h4><p>{e(p['delivery'])}</p><h4>Uma pergunta que provoca</h4><p>{e(p['challenge'])}</p><h4>Na prática</h4><p>{e(p['example'])}</p><p class="expert-limit"><strong>Um limite importante:</strong> {e(p['limit'])}</p></div></details></article>''')
    interest=contact_link(phone,'Quero conhecer o Prisma e conversar sobre o futuro piloto gratuito.','Quero conhecer o futuro piloto','prisma-interest','prisma-contact-note')
    services=contact_link(phone,'Conheci o Prisma e quero ajuda da Mescla para implantar um time de IA na minha rotina.','Quero ajuda para implementar','prisma-service','prisma-service-note')
    learning=contact_link(phone,'Conheci o Prisma e quero aprender a criar meus próprios agentes de IA.','Quero aprender a construir','prisma-learning','prisma-learning-note')
    diagram='''<svg viewBox="0 0 620 350" role="img" aria-labelledby="prism-title prism-desc"><title id="prism-title">Uma decisão, oito perspectivas</title><desc id="prism-desc">Uma linha entra em um prisma e se abre em oito linhas coloridas, representando áreas de análise diferentes.</desc><defs><linearGradient id="prism-glass" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#fff" stop-opacity=".75"/><stop offset="1" stop-color="#bdb0eb" stop-opacity=".14"/></linearGradient></defs><g fill="none" stroke-width="2"><path d="M24 182H228" stroke="#faf3d6"/><path d="M299 178 567 43" stroke="#c9abff"/><path d="M308 184 583 99" stroke="#b6bbff"/><path d="M317 190 595 155" stroke="#9bd5d5"/><path d="M325 196 595 211" stroke="#f1d27e"/><path d="M334 202 583 267" stroke="#f0b29c"/><path d="M343 208 567 323" stroke="#e2a3cc"/><path d="M304 181 575 71" stroke="#aecfe0"/><path d="M338 205 575 295" stroke="#c5cf9d"/></g><path d="m269 60-101 232 253-39Z" fill="url(#prism-glass)" stroke="#e0d4ff" stroke-width="1.5"/><path d="m269 60 21 198-122 34m122-34 131-5" fill="none" stroke="#e0d4ff" stroke-opacity=".6"/><circle cx="24" cy="182" r="5" fill="#faf3d6"/><g fill="#f6f1ff"><circle cx="567" cy="43" r="4"/><circle cx="583" cy="99" r="4"/><circle cx="595" cy="155" r="4"/><circle cx="595" cy="211" r="4"/><circle cx="583" cy="267" r="4"/><circle cx="567" cy="323" r="4"/><circle cx="575" cy="71" r="4"/><circle cx="575" cy="295" r="4"/></g></svg>'''
    return f'''<!DOCTYPE html>
<html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#251c38"><title>Prisma, da Mescla · Mais perspectivas para decidir</title><meta name="description" content="Conheça os oito especialistas de IA do Prisma e o método com curadoria de André de Moraes. Uma experiência gratuita de apoio à decisão, em preparação."><link rel="canonical" href="https://mescla.ai/prisma/"><meta property="og:type" content="website"><meta property="og:locale" content="pt_BR"><meta property="og:title" content="Prisma · Uma decisão. Mais perspectivas."><meta property="og:description" content="Especialistas de IA com métodos distintos, argumentos em confronto e a decisão nas suas mãos. Uma criação da Mescla.AI, em preparação."><meta property="og:url" content="https://mescla.ai/prisma/"><link rel="icon" type="image/svg+xml" href="{favicon}">{font}<style>{css}</style><link rel="stylesheet" href="{style_href}"><link rel="stylesheet" href="{prisma_href}"></head>
<body class="prisma-page" data-segment="prisma" data-segment-label="Prisma" data-page-version="2026-10-prisma-specialists-v4">
<a class="skip" href="#principal">Pular para o conteúdo</a><header class="nav"><div class="wrap nav-inner">{brand('/')}<nav class="prisma-nav" aria-label="Navegação Prisma"><a href="#especialistas">Os especialistas</a><a href="#metodo">O método</a><a href="#acompanhar">Acompanhar</a></nav></div></header>
<main id="principal">
<section class="prisma-hero" aria-labelledby="prisma-title"><div class="wrap prisma-hero-grid"><div><p class="eyebrow">Prisma · uma criação da Mescla.AI</p><h1 id="prisma-title">Sua decisão merece<br><em>outros olhares.</em></h1><p class="lead">Há escolhas que mudam quando você conecta o que o cliente precisa, o que a conta permite e o que a rotina exige.</p><p class="prisma-hero-copy">Estamos preparando uma experiência gratuita que combina especialistas de IA, skills exclusivas da Mescla e modelos diferentes em um looping adversarial: analisar, questionar e revisar. Você continua decidindo.</p><ul class="prisma-pillars" aria-label="Bases do Prisma"><li>Looping adversarial</li><li>Skills exclusivas</li><li>Modelos diferentes</li></ul><div class="prisma-hero-actions"><a class="btn" href="#especialistas">Conheça os especialistas <span aria-hidden="true">↓</span></a><a class="text-link" href="#metodo">Veja como pensamos</a></div><p class="prisma-status"><span aria-hidden="true"></span>Em preparação · acesso à análise ainda não disponível</p></div><figure class="prisma-figure">{diagram}<figcaption>Uma questão entra.<br><strong>Perspectivas diferentes se encontram.</strong></figcaption></figure></div></section>
<section class="section prisma-curation" aria-labelledby="curation-title"><div class="wrap curation-grid"><div><p class="eyebrow">Curadoria de André de Moraes</p><h2 id="curation-title">A forma de trabalhar<br>da Mescla, em cada olhar.</h2></div><div><p class="lead">Conectar conhecimentos. Questionar a primeira resposta. Transformar uma ideia em algo que funciona na vida real.</p><p>Esses critérios orientam a construção dos especialistas do Prisma. Cada um tem uma responsabilidade, métodos e limites próprios. Juntos, traduzem a abordagem multidisciplinar que André leva ao trabalho da Mescla.</p><p class="curation-note">São agentes de IA com curadoria de método. As respostas não significam uma opinião pessoal de André nem uma revisão individual feita por ele.</p></div></div></section>
<section class="section prisma-experts" id="especialistas" aria-labelledby="experts-title"><div class="wrap"><div class="prisma-section-head"><div><p class="eyebrow">Oito disciplinas · responsabilidades distintas</p><h2 id="experts-title">Cada especialista percebe<br>uma parte da questão.</h2></div><p class="lead">O elenco inicial foi pensado para decisões de trabalho e negócio, de quem atua sozinho a quem lidera uma empresa. A seleção acompanha a pergunta. Pesquisa e Evidências apoia todas as disciplinas; IA e Dados examina a capacidade técnica das soluções.</p></div><div class="expert-grid">{''.join(cards)}</div><p class="prisma-caption">As especialidades são funções de análise por IA. Cada uma deve aplicar seu método e explicitar o que falta saber.</p></div></section>
<section class="section prisma-toolbox" id="repertorio" aria-labelledby="toolbox-title"><div class="wrap"><div class="prisma-section-head"><div><p class="eyebrow">Estratégia e Futuros · 14 instrumentos</p><h2 id="toolbox-title">Um canivete suíço.<br>O instrumento certo para a questão.</h2></div><p class="lead">Cada decisão pede uma combinação. O especialista pode investigar uma mudança, aprofundar suas causas, explorar futuros ou testar um caminho. O repertório orienta a escolha do método.</p></div>
<div class="prisma-repertoire">
<article><span class="tool-stage">01 · Sinais e tendências</span><h3>Perceber o que está mudando.</h3><p>Horizon scanning, STEEPED / PESTLE e Matriz de Impacto × Incerteza.</p><details><summary>Como esses instrumentos ajudam</summary><p>A varredura busca sinais emergentes. STEEPED examina dimensões sociais, tecnológicas, econômicas, ecológicas, políticas, éticas e demográficas; PESTLE oferece outra classificação, incluindo legislação. A matriz destaca forças que podem afetar a decisão e cujo rumo é incerto.</p><p><strong>Entrega:</strong> um mapa de sinais, fontes, lacunas e prioridades de investigação.</p></details></article>
<article><span class="tool-stage">02 · Impactos e pressupostos</span><h3>Enxergar além da primeira consequência.</h3><p>Análise Causal em Camadas (CLA) e Roda de Futuros.</p><details><summary>Como esses instrumentos ajudam</summary><p>A CLA, de Sohail Inayatullah, examina a descrição visível, as causas sistêmicas, as visões de mundo e as metáforas. A Roda de Futuros, de Jerome Glenn, explora efeitos diretos e suas consequências. As interpretações precisam de verificação.</p><p><strong>Entrega:</strong> pressupostos a questionar e impactos que podem mudar a escolha.</p></details></article>
<article><span class="tool-stage">03 · Construção de cenários</span><h3>Abrir espaço para futuros diferentes.</h3><p>Cone de Futuros, matriz 2×2 e arquétipos de Dator.</p><details><summary>Como esses instrumentos ajudam</summary><p>O cone distingue possibilidades, plausibilidade, expectativa e preferência. A matriz cruza duas incertezas relevantes. Dator propõe explorar continuação, colapso, disciplina e transformação. Cada narrativa precisa ter consequências para a decisão.</p><p><strong>Entrega:</strong> cenários contrastantes, com premissas e sinais para acompanhá-los.</p></details></article>
<article><span class="tool-stage">04 · Estratégia e ação</span><h3>Trazer o futuro para o presente.</h3><p>Backcasting, Artefatos do Futuro e wind tunnelling, apoiados por Três Horizontes, roteiro por condições e opções reversíveis.</p><details><summary>Como esses instrumentos ajudam</summary><p>Partir do futuro desejado para descobrir condições necessárias. Tornar um cenário tangível em um artefato identificado como ficção. Testar a estratégia em futuros distintos. Planejar a transição e definir quando avançar, adaptar ou parar.</p><p><strong>Entrega:</strong> uma escolha examinada e um próximo passo verificável.</p></details></article>
</div><p class="prisma-caption">O repertório está documentado nas skills. Os métodos são selecionados conforme a pergunta; cenários não são previsões e uma consulta não implica monitoramento contínuo. A nova versão ainda passará por avaliação comparativa.</p></div></section>
<section class="section prisma-method" id="metodo" aria-labelledby="method-title"><div class="wrap"><div class="prisma-section-head"><div><p class="eyebrow">Looping adversarial</p><h2 id="method-title">Uma análise precisa<br>resistir a boas objeções.</h2></div><p class="lead">Chamamos de looping adversarial o ciclo em que os especialistas analisam separadamente, confrontam afirmações e revisam suas posições. A discordância precisa ajudar a decidir.</p></div>
<ol class="prisma-steps"><li><span>01 · Contexto comum</span><h3>Delimitar e pesquisar</h3><p>Esclarecer opções e limites. Pesquisa e Evidências organiza fontes e lacunas para os especialistas selecionados.</p></li><li><span>02 · Independência</span><h3>Analisar com método</h3><p>Cada especialista aplica sua skill antes de conhecer as conclusões dos demais. A primeira análise é preservada.</p></li><li><span>03 · Confronto</span><h3>Questionar uma afirmação</h3><p>Apontar o argumento contestado, o que o sustenta e como uma falha mudaria a recomendação.</p></li><li><span>04 · Verificação</span><h3>Buscar o que falta</h3><p>Conferir fontes e contas quando puderem mudar a escolha. Mostrar a lacuna quando a informação não estiver disponível.</p></li><li><span>05 · Revisão</span><h3>Explicar o que mudou</h3><p>Manter, alterar ou retirar uma posição com justificativa. Outra rodada só acontece se houver uma questão relevante a resolver.</p></li><li><span>06 · Decisão humana</span><h3>Sintetizar sem apagar o dissenso</h3><p>Entregar alternativas, condições, divergências e próximo passo. O ciclo termina por limite, falta de dados ou estabilidade dos argumentos.</p></li></ol>
<div class="prisma-foundations"><article><p class="eyebrow">Skills exclusivas da Mescla</p><h3>Um repertório próprio para cada olhar.</h3><p>Construímos pacotes de instruções com perguntas, métodos, referências, entregáveis e critérios de revisão. Eles orientam como cada especialista trabalha e conectam sua análise à curadoria de André.</p><p class="prisma-caption">A composição das skills é própria. Os métodos clássicos são atribuídos a seus autores; isso não significa que treinamos modelos exclusivos.</p></article><article><p class="eyebrow">Modelos diferentes</p><h3>Mais de uma família de IA à mesa.</h3><p>O desenho do Prisma combina motores diferentes com responsabilidades específicas. A especialidade vem da skill; o modelo executa a análise. Os ensaios iniciais já exploraram essa combinação.</p><p class="prisma-caption">A composição pode mudar conforme os testes e a disponibilidade. Modelos diferentes também podem compartilhar erros; a versão atual ainda precisa ser avaliada.</p></article></div>
<details class="prisma-sources"><summary>Pesquisa que orienta o método</summary><div><p>Estudos de <a href="https://arxiv.org/abs/2305.14325">Du e colaboradores</a> e do <a href="https://aclanthology.org/2024.acl-long.381/">ReConcile</a> relatam ganhos com debate e diversidade de modelos em tarefas específicas. <a href="https://proceedings.mlr.press/v235/smit24a.html">Smit e colaboradores</a> e <a href="https://arxiv.org/abs/2502.08788">Zhang e colaboradores</a> mostram por que o ganho precisa ser comparado com alternativas mais simples.</p><p>Para Futuros, consultamos o <a href="https://www.gov.uk/government/publications/futures-toolkit-for-policy-makers-and-analysts/the-futures-toolkit-html">Futures Toolkit</a>, <a href="https://www.metafuture.org/cla-home/">Inayatullah</a>, <a href="https://thevoroscope.com/2017/02/24/the-futures-cone-use-and-history/">Voros</a>, <a href="https://jfsdigital.org/articles-and-essays/2009-2/vol-14-no-2-november/articles/futuristsalternative-futures-at-the-manoa-school/">Dator</a>, <a href="https://www.millennium-project.org/overview/organization/jerome-glenn-executive-director/">Glenn</a>, <a href="https://legacy.iftf.org/what-we-do/artifacts-from-the-future/">IFTF</a> e a <a href="https://www.shell.com/news-and-insights/scenarios/what-are-shell-scenarios.html">prática de cenários da Shell</a>. A matriz 2×2 é uma técnica, não o método completo da Shell.</p><p>Essas referências orientam a construção e não constituem endosso ou validação do Prisma. Fontes consultadas em 30/10/2026.</p></div></details>
</div></section>
<section class="section prisma-example" aria-labelledby="example-title"><div class="wrap example-grid"><div><p class="eyebrow">Exemplo ilustrativo · não é uma análise executada</p><h2 id="example-title">“Compensa lançar<br>meu novo serviço?”</h2><p class="lead">Uma mesma pergunta abre conversas diferentes.</p><p>O resultado pode ser lançar, adaptar a proposta ou descobrir primeiro uma informação decisiva.</p></div><div class="example-notes"><article><span>Cliente e produto</span><p>Quem sente esse problema e como resolve hoje?</p></article><article><span>Economia e preço</span><p>O preço cobre também seu tempo de atendimento?</p></article><article><span>Tecnologia e operação</span><p>Qual é a menor entrega que você consegue testar?</p></article><div class="example-outcome"><strong>Um possível próximo passo</strong><p>Testar uma oferta pequena com um público definido e um limite de esforço, antes de construir toda a operação.</p></div></div></div></section>
<section class="section prisma-principles" aria-labelledby="principles-title"><div class="wrap"><p class="eyebrow">O compromisso do método</p><h2 id="principles-title">Clareza também é saber o limite.</h2><div class="principle-grid"><article><h3>Evidência antes de confiança</h3><p>Separar o que foi observado, o que é hipótese e o que precisa de verificação. Vários agentes podem repetir o mesmo erro.</p></article><article><h3>Autonomia antes de persuasão</h3><p>Uma análise pode concluir que você não precisa de IA, de um projeto novo ou de contratar a Mescla.</p></article><article><h3>Cuidado antes de certeza</h3><p>Reconhecer quando a decisão exige apoio profissional e ajudar a preparar as perguntas. Sem promessa de infalibilidade.</p></article></div></div></section>
<section class="section prisma-follow" id="acompanhar" aria-labelledby="follow-title"><div class="wrap follow-grid"><div><p class="eyebrow">Prisma está em preparação</p><h2 id="follow-title">Quer conhecer<br>essa experiência?</h2><p class="lead">A proposta é começar com um piloto gratuito de decisões de trabalho e negócio. O acesso ainda não está aberto.</p>{interest}<p class="contact-expectation" id="prisma-contact-note">O botão abre uma mensagem para você revisar e enviar pelo WhatsApp. Não faz inscrição automática em grupo ou lista.</p><p class="prisma-caption">Esta página não recebe o conteúdo da sua decisão. Evite enviar informações confidenciais no primeiro contato. <a href="/privacidade/">Como usamos as informações</a>.</p></div><div class="prisma-next"><p class="eyebrow">Enquanto isso, a Mescla já pode ajudar</p><article><h3>Um time de IA para sua rotina.</h3><p>Implantação e consultoria para pessoas físicas e empresas, a partir do trabalho que precisam realizar.</p>{services}<p id="prisma-service-note" class="contact-expectation">Conversa sobre escopo e investimento pelo WhatsApp.</p></article><article><h3>Aprenda a construir o seu.</h3><p>Converse sobre orientação para criar agentes e aplicar IA no seu trabalho.</p>{learning}<p id="prisma-learning-note" class="contact-expectation">Conversa sobre objetivo e formato de aprendizagem.</p></article></div></div></section>
</main>{footer}<script src="/assets/measurement-config.js"></script><script src="/assets/measurement.js" defer></script></body></html>'''
